"function windowedPoints(){
  var cutoff = Date.now()-(windowSecs*1000)-RIGHT_BUFFER_MS, out=[];
  for(var i=0;i<allPoints.length;i++){if(allPoints[i].ts>=cutoff)out.push(allPoints[i]);}
  return out;
}"

